import{_ as a,m as s,p as o,a9 as i}from"./chunks/framework.Kh3mV7y8.js";const m=JSON.parse('{"title":"File Types","description":"File types that are supported by Minecraft.","frontmatter":{"title":"File Types","description":"File types that are supported by Minecraft.","mentions":["Ciosciaa","SirLich"]},"headers":[{"level":2,"title":"Levels","slug":"levels","link":"#levels","children":[{"level":3,"title":"Worlds","slug":"worlds","link":"#worlds","children":[]},{"level":3,"title":"Projects","slug":"projects","link":"#projects","children":[]}]},{"level":2,"title":"Assets","slug":"assets","link":"#assets","children":[{"level":3,"title":"Packs","slug":"packs","link":"#packs","children":[{"level":4,"title":"Behavior Packs","slug":"behavior-packs","link":"#behavior-packs","children":[]},{"level":4,"title":"Resource Packs","slug":"resource-packs","link":"#resource-packs","children":[]},{"level":4,"title":"Skin Packs","slug":"skin-packs","link":"#skin-packs","children":[]}]},{"level":3,"title":"World Templates","slug":"world-templates","link":"#world-templates","children":[]}]},{"level":2,"title":"Composites","slug":"composites","link":"#composites","children":[{"level":3,"title":"Add-Ons","slug":"add-ons","link":"#add-ons","children":[]},{"level":3,"title":"Editor Add-Ons","slug":"editor-add-ons","link":"#editor-add-ons","children":[]}]}],"relativePath":"documentation/file-types.md","filePath":"documentation/file-types.md"}'),t={name:"documentation/file-types.md"};function n(c,e,r,l,d,p){return s(),o("div",null,[...e[0]||(e[0]=[i('<p>A number of file types exist for <em>Minecraft</em>, all for importing content. All <em>Minecraft</em> files are ZIP archives renamed to use a <code class="shiki"><span>mc…</span></code> extension. These archives can currently be divided into three sets:</p><ul><li><strong>Levels (<code class="shiki"><span>mcworld</span></code> and <code class="shiki"><span>mcproject</span></code>)</strong>: level data and associated resources for worlds and projects</li><li><strong>Assets (<code class="shiki"><span>mcpack</span></code> and <code class="shiki"><span>mctemplate</span></code>)</strong>: cosmetics or supporting assets for worlds</li><li><strong>Composites (<code class="shiki"><span>mcaddon</span></code> and <code class="shiki"><span>mceditoraddon)</span></code></strong>: used to import up to one world or project and any number of asset types</li></ul><p>All file types for Minecraft can be opened as any file, launching Minecraft and importing the content. When packages are imported, they are automatically unpacked into their constituent files and directories. If it was not already open, most file types will launch Minecraft in normal mode; <code class="shiki"><span>mcproject</span></code> and <code class="shiki"><span>mceditoraddon</span></code> will instead launch Minecraft into Editor mode.</p><h2 id="levels" tabindex="-1">Levels <a class="header-anchor" href="#levels" aria-label="Permalink to &quot;Levels&quot;">​</a></h2><p>Levels represent save data and resources for regular worlds and Editor projects. All levels, regardless of mode, are imported to <code class="shiki"><span>minecraftWorlds</span></code> in the <code class="shiki"><span>com.mojang</span></code> directory.</p><p>Importing an exact duplicate of an existing saved level will create a duplicate saved level. Composite archives will only import one level if multiple are included, including across nested composite archives.</p><h3 id="worlds" tabindex="-1">Worlds <a class="header-anchor" href="#worlds" aria-label="Permalink to &quot;Worlds&quot;">​</a></h3><p><code class="shiki"><span>mcworld</span></code> Archive encapsulating an individual world</p><p>World archives can be created a few different ways:</p><ul><li>Zipping the <em>contents</em> of a world directory and renaming the extension from <code class="shiki"><span>zip</span></code> to <code class="shiki"><span>mcworld</span></code></li><li>Using the &quot;Export World&quot; button on the Game settings screen for a world</li><li>In Editor mode, exporting the world from the File → Export as → Playable world menu option. The world will be saved to the <code class="shiki"><span>projectbackups</span></code> directory in the <code class="shiki"><span>com.mojang</span></code> folder.</li><li>In Editor mode, running the <code class="shiki"><span>/project export world</span></code> command. The world will be saved to the <code class="shiki"><span>projectbackups</span></code> directory in the <code class="shiki"><span>com.mojang</span></code> folder.</li></ul><p>Importing a world package while <em>Minecraft</em> is launched in Editor mode will import the world as a project. The imported world will then be inaccessible outside Editor mode and will need to be re-exported as a world for playing. Editor extension packs bundled in a world archive will be retained on import outside Editor mode.</p><h3 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h3><p><code class="shiki"><span>mcproject</span></code> Archive encapsulating an individual Editor project</p><p>Project archives can be created two different ways:</p><ul><li>Zipping the <em>contents</em> of a project directory and renaming the extension from <code class="shiki"><span>zip</span></code> to <code class="shiki"><span>mcproject</span></code>.</li><li>Using the &quot;Export Project&quot; button on the Game settings screen for a world</li><li>In Editor mode, running the <code class="shiki"><span>/project export project</span></code> command. The world will be saved to the <code class="shiki"><span>projectbackups</span></code> directory in the <code class="shiki"><span>com.mojang</span></code> folder.</li></ul><p>If <em>Minecraft</em> is not open, launching a <code class="shiki"><span>mcproject</span></code> file will open Editor mode. Importing a <code class="shiki"><span>mcproject</span></code> will fail if <em>Minecraft</em> is open but not in Editor mode.</p><h2 id="assets" tabindex="-1">Assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Assets&quot;">​</a></h2><p>Asset archives represent a singular instance of a number of non-level contents:</p><ul><li>Behavior packs</li><li>Resource packs</li><li>Skin packs</li><li>World templates</li></ul><p>All asset archives include a manifest describing their contents. An asset archive will fail to import if its manifest UUID and version exactly matches an existing asset archive of the same type. Note that behavior and resource packs share the same UUID/version space. Behavior and resource packs self-contained within a world, project, or template will not count as duplicates for the sake of importing.</p><p>Both asset extensions, <code class="shiki"><span>mcpack</span></code> and <code class="shiki"><span>mctemplate</span></code>, appear to functionally behave the same. It&#39;s best practice to use <code class="shiki"><span>mcpack</span></code> for behavior, resource, and skin packs and <code class="shiki"><span>mctemplate</span></code> for world templates to make it more clear what&#39;s being installed. Any number of asset archives may be included in a composite archive.</p><h3 id="packs" tabindex="-1">Packs <a class="header-anchor" href="#packs" aria-label="Permalink to &quot;Packs&quot;">​</a></h3><p><code class="shiki"><span>mcpack</span></code> Package representing an individual behavior pack, resource pack, skin pack, or world template. It&#39;s recommended only to use <code class="shiki"><span>mctemplate</span></code> for behavior packs, resource packs, or skin packs.</p><p>Packs are only created manually, by zipping the contents of a behavior pack, resource pack, or skin pack directory and renaming the extension from <code class="shiki"><span>zip</span></code> to <code class="shiki"><span>mcpack</span></code>. Behavior and resource packs are installed globally and do not conflict with matching behavior or resource packs installed in worlds, projects, or templates.</p><h4 id="behavior-packs" tabindex="-1">Behavior Packs <a class="header-anchor" href="#behavior-packs" aria-label="Permalink to &quot;Behavior Packs&quot;">​</a></h4><p>Behavior packs are attached to servers to change or extend gameplay. Behavior packs are installed to the <code class="shiki"><span>behavior_packs</span></code> directory in the <code class="shiki"><span>com.mojang</span></code> folder.</p><p>Development behavior packs must be placed in the <code class="shiki"><span>development_behavior_packs</span></code> directory under <code class="shiki"><span>com.mojang</span></code> manually.</p><h4 id="resource-packs" tabindex="-1">Resource Packs <a class="header-anchor" href="#resource-packs" aria-label="Permalink to &quot;Resource Packs&quot;">​</a></h4><p>Resource packs are attached to clients to affect sounds, visuals, etc. Resource packs are installed to the <code class="shiki"><span>resource_packs</span></code> directory in the <code class="shiki"><span>com.mojang</span></code> folder.</p><p>Development resource packs must be placed in the <code class="shiki"><span>development_resource_packs</span></code> directory under <code class="shiki"><span>com.mojang</span></code> manually.</p><h4 id="skin-packs" tabindex="-1">Skin Packs <a class="header-anchor" href="#skin-packs" aria-label="Permalink to &quot;Skin Packs&quot;">​</a></h4><p>Skin packs are client-only packs for custom skins. Skin packs are installed to the <code class="shiki"><span>skin_packs</span></code> directory in the <code class="shiki"><span>com.mojang</span></code> folder.</p><p>Development skin packs must be placed in the <code class="shiki"><span>development_skin_packs</span></code> directory under <code class="shiki"><span>com.mojang</span></code> manually, but this feature appears non-functional.</p><h3 id="world-templates" tabindex="-1">World Templates <a class="header-anchor" href="#world-templates" aria-label="Permalink to &quot;World Templates&quot;">​</a></h3><p><code class="shiki"><span>mctemplate</span></code> Package representing an individual behavior pack, resource pack, skin pack, or world template. It&#39;s recommended only to use <code class="shiki"><span>mctemplate</span></code> for world templates.</p><p>World templates are installed to the <code class="shiki"><span>world_templates</span></code> directory under <code class="shiki"><span>com.mojang</span></code>. World templates can be constructed in a few different ways:</p><ul><li>Zipping the <em>contents</em> of a world directory, adding a world template manifest, and renaming the extension from <code class="shiki"><span>zip</span></code> to <code class="shiki"><span>mctemplate</span></code></li><li>In Editor mode, using the &quot;Export Template&quot; button on the Game settings screen for a world</li><li>In Editor mode, running the <code class="shiki"><span>/project export template</span></code> command. The world will be saved to the <code class="shiki"><span>projectbackups</span></code> directory in the <code class="shiki"><span>com.mojang</span></code> folder.</li></ul><h2 id="composites" tabindex="-1">Composites <a class="header-anchor" href="#composites" aria-label="Permalink to &quot;Composites&quot;">​</a></h2><p>Composite archives are used to import up to <em>one</em> level archive and any number or combination of asset archives in a single import action. In general, contents to a composite must be packaged. Directories can also be given <em>on the top level</em> of a composite archive for importing asset types (behavior packs, resource packs, skin packs, and world templates) without needing to pre-package them. Nested sub-directories for organization may not be used.</p><p>Composite contents are treated as usual. For example, importing a <code class="shiki"><span>mcaddon</span></code> containing a <code class="shiki"><span>mcworld</span></code> while in Editor mode will import the world as a project.</p><p>Composite archives may also contain any number or nesting of other composite archives, even across <em>Minecraft</em> modes. Nested composite archives cannot be used to get around the singular world import restriction.</p><p>Composites can only be constructed manually by zipping archives and asset types.</p><h3 id="add-ons" tabindex="-1">Add-Ons <a class="header-anchor" href="#add-ons" aria-label="Permalink to &quot;Add-Ons&quot;">​</a></h3><p><code class="shiki"><span>mcaddon</span></code> Generic composite content archive</p><p>Importing a <code class="shiki"><span>mcaddon</span></code> package while <em>Minecraft</em> is launched in Editor mode will import any contained world as a project. The imported world will then be inaccessible outside Editor mode and will need to be re-exported as a world for playing. Asset types are imported as usual.</p><h3 id="editor-add-ons" tabindex="-1">Editor Add-Ons <a class="header-anchor" href="#editor-add-ons" aria-label="Permalink to &quot;Editor Add-Ons&quot;">​</a></h3><p><code class="shiki"><span>mceditoraddon</span></code> Composite content archive for Editor mode</p><p>If <em>Minecraft</em> is not open, launching a <code class="shiki"><span>mcproject</span></code> file will open Editor mode. Importing a <code class="shiki"><span>mcproject</span></code> will fail if <em>Minecraft</em> is open but not in Editor mode.</p>',48)])])}const k=a(t,[["render",n]]);export{m as __pageData,k as default};
